import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ChevronDown, ChevronUp, MessageCircle } from "lucide-react";
import MessagePopup from "./MessagePopup";

const TYPE_META = {
  blog:        { icon: "📝", label: "Blog",        cls: "text-green-400  bg-green-500/10  border-green-500/30"  },
  publication: { icon: "📄", label: "Publication", cls: "text-blue-400   bg-blue-500/10   border-blue-500/30"   },
  paper:       { icon: "🔬", label: "Paper",       cls: "text-yellow-400 bg-yellow-500/10 border-yellow-500/30" },
  research:    { icon: "🧪", label: "Research",    cls: "text-purple-400 bg-purple-500/10 border-purple-500/30" },
};

const fmtDate = (d) => {
  try { return new Date(d).toLocaleDateString("en-US", { year: "numeric", month: "short" }); }
  catch { return d; }
};

export default function BlogPost({
  title, tags = [], date,
  type = "blog", excerpt, content, author, url, cover,
}) {
  const [expanded, setExpanded]     = useState(false);
  const [showDiscuss, setShowDiscuss] = useState(false);

  const meta       = TYPE_META[type] || TYPE_META.blog;
  const hasUrl     = !!url;
  const hasContent = !!content;

  const handleClick = () => {
    if (hasUrl)     { window.open(url, "_blank", "noreferrer"); return; }
    if (hasContent) setExpanded(e => !e);
  };

  return (
    <>
      <motion.div
        className="group bg-[#0d1117] border border-green-500/20 rounded-2xl overflow-hidden flex flex-col
                   hover:border-green-400/50 hover:shadow-[0_0_24px_rgba(34,197,94,0.12)]
                   transition-all duration-300 cursor-pointer"
        whileHover={{ y: -2 }}
        transition={{ duration: 0.2 }}
        onClick={handleClick}
      >
        {/* ── Top accent bar ── */}
        <div className="h-[2px] bg-gradient-to-r from-transparent via-green-500/40 to-transparent
                        group-hover:via-green-400/70 transition-all duration-300" />

        {/* ── Cover image ── */}
        {cover && (
          <div className="w-full h-40 overflow-hidden">
            <img
              src={`${process.env.PUBLIC_URL}/${cover}`}
              alt={title}
              className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
            />
          </div>
        )}

        {/* ── Body ── */}
        <div className="px-5 pt-4 pb-3 flex-1 flex flex-col gap-3">

          {/* Type badge + date */}
          <div className="flex items-center justify-between gap-2">
            <span className={`inline-flex items-center gap-1.5 text-[10px] font-mono font-bold
                              uppercase tracking-widest px-2.5 py-1 rounded-full border ${meta.cls}`}>
              <span className="text-[12px]">{meta.icon}</span>
              {meta.label}
            </span>
            {date && (
              <span className="text-[11px] text-gray-600 font-mono tabular-nums">{fmtDate(date)}</span>
            )}
          </div>

          {/* Title */}
          <h3 className="text-white text-[15px] font-semibold leading-snug
                         group-hover:text-green-300 transition-colors duration-200 line-clamp-2">
            {title}
          </h3>

          {/* Excerpt */}
          {excerpt && (
            <p className="text-gray-500 text-sm leading-relaxed line-clamp-2 flex-1">{excerpt}</p>
          )}

          {/* Tags */}
          {tags.length > 0 && (
            <div className="flex flex-wrap gap-1.5 pt-1">
              {tags.slice(0, 4).map((tag, i) => (
                <span key={i} className="text-[10px] px-2 py-0.5 rounded-full
                                         bg-[#0b1320] border border-green-500/20
                                         text-gray-400 font-mono">
                  {tag}
                </span>
              ))}
            </div>
          )}
        </div>

        {/* ── Footer ── */}
        <div className="px-5 py-3 border-t border-green-500/10 bg-[#0a0d12]
                        flex items-center justify-between gap-3">
          {/* Discuss button */}
          <button
            onClick={(e) => { e.stopPropagation(); setShowDiscuss(true); }}
            className="flex items-center gap-1.5 text-gray-500 hover:text-green-400 transition text-[11px] font-mono"
          >
            <MessageCircle size={13} />
            DISCUSS
          </button>

          {hasUrl && (
            <span className="flex items-center gap-1 text-green-400/70 group-hover:text-green-400
                             text-[11px] font-medium font-mono transition-colors">
              READ ↗
            </span>
          )}
          {!hasUrl && hasContent && (
            <span className="flex items-center gap-1 text-green-400/70 group-hover:text-green-400
                             text-[11px] font-medium font-mono transition-colors">
              {expanded ? "CLOSE" : "EXPAND"}
              {expanded ? <ChevronUp size={11} /> : <ChevronDown size={11} />}
            </span>
          )}
        </div>

        {/* ── Expanded inline content ── */}
        <AnimatePresence>
          {expanded && hasContent && (
            <motion.div
              key="body"
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.25 }}
              className="px-5 pb-5 border-t border-green-500/10 bg-[#0a0d12]"
            >
              <p className="text-gray-300 text-sm leading-relaxed pt-4 whitespace-pre-wrap">{content}</p>
              {author && <p className="text-gray-600 text-xs mt-3 italic">— {author}</p>}
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>

      <MessagePopup open={showDiscuss} onClose={() => setShowDiscuss(false)} />
    </>
  );
}
