import React from "react";
import { motion } from "framer-motion";
import { ArrowLeft } from "lucide-react";
import { EXPERIENCE_ROLES } from "../data/experienceData";

const MONTH_MAP = {
  Jan:0, Feb:1, Mar:2, Apr:3, May:4, Jun:5,
  Jul:6, Aug:7, Sep:8, Oct:9, Nov:10, Dec:11,
};

// Supports both "–" (en-dash) and "-" (hyphen) as separators
const parsePeriod = (period) => {
  if (!period) return 0;
  const parts = period.split(/\s[–-]\s/);
  if (parts.length < 2) return 0;
  const [startStr, endStr] = parts;
  const [startMonth, startYear] = (startStr || "").split(" ");
  const isPresent = endStr.trim() === "Present";
  const [endMonth, endYear] = isPresent ? ["Present", new Date().getFullYear()] : (endStr || "").split(" ");
  const s0 = MONTH_MAP[startMonth];
  const e0 = isPresent ? new Date().getMonth() : MONTH_MAP[endMonth];
  const sy = parseInt(startYear, 10);
  const ey = isPresent ? new Date().getFullYear() : parseInt(endYear, 10);
  if (isNaN(sy) || isNaN(ey) || s0 === undefined || (!isPresent && e0 === undefined)) return 0;
  return Math.max((ey - sy) * 12 + (e0 - s0), 0);
};

const getTotalExperienceYears = () => {
  try {
    const total = (EXPERIENCE_ROLES || []).reduce((sum, r) => sum + parsePeriod(r.period), 0);
    return (total / 12).toFixed(1);
  } catch {
    return "0.0";
  }
};

const getCurrentCompany = () => {
  try {
    const current = (EXPERIENCE_ROLES || []).find(r => (r.period || "").includes("Present"));
    return current?.company ?? EXPERIENCE_ROLES?.[0]?.company ?? "";
  } catch {
    return "";
  }
};

export default function ExperiencePage({ onNavigate }) {
  const totalExperience = getTotalExperienceYears();
  const companyCount    = (EXPERIENCE_ROLES || []).length;
  const currentCompany  = getCurrentCompany();

  return (
    <div className="min-h-screen bg-[#0b0f16] text-white">
      <div className="pt-14 pb-8 px-4 max-w-5xl mx-auto">
        <button
          onClick={() => onNavigate?.("home")}
          className="inline-flex items-center gap-2 text-green-300 hover:text-white text-sm font-medium mb-6"
        >
          <ArrowLeft size={18} />
          Back to Portfolio
        </button>

        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center mb-10"
        >
          <h1 className="text-3xl md:text-4xl font-bold text-green-400">Professional Experience</h1>
          <p className="text-gray-400 mt-4 text-base max-w-3xl mx-auto">
            {totalExperience} years across finance, engineering &amp; research.
          </p>
        </motion.div>

        <div className="grid gap-3 grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 mb-6">
          {[
            { label: "Total Experience", value: `${totalExperience}y` },
            { label: "Companies",        value: companyCount },
            { label: "Domains",          value: "Quant • ML • SWE" },
            { label: "Current",          value: currentCompany },
          ].map(({ label, value }) => (
            <div key={label} className="bg-[#0d1117] border border-green-500/20 rounded-2xl p-3 text-center hover:border-green-400 transition">
              <p className="text-lg md:text-xl font-bold text-green-400">{value}</p>
              <p className="text-gray-400 text-[11px] mt-2">{label}</p>
            </div>
          ))}
        </div>

        <div className="grid gap-4 lg:grid-cols-2">
          {(EXPERIENCE_ROLES || []).map((experience, idx) => (
            <motion.div
              key={`${experience.company}-${experience.role}-${idx}`}
              initial={{ opacity: 0, y: 24 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.05 }}
              className="bg-[#0d1117] border border-green-500/20 rounded-2xl p-3 hover:border-green-400 hover:shadow-[0_0_10px_rgba(34,197,94,0.08)] transition"
            >
              <div className="flex items-start gap-4 mb-4">
                {experience.logo ? (
                  <img
                    src={experience.logo}
                    alt={experience.company}
                    className="w-14 h-14 rounded-xl object-contain bg-white p-2 shadow-md flex-shrink-0"
                  />
                ) : (
                  <div className="w-14 h-14 rounded-xl bg-green-500/10 border border-green-500/20 flex items-center justify-center flex-shrink-0 text-green-400 font-bold text-lg">
                    {(experience.company || "?").charAt(0)}
                  </div>
                )}
                <div className="flex-1">
                  <p className="text-[10px] uppercase tracking-[0.2em] text-green-400 font-semibold">{experience.role}</p>
                  <h2 className="text-base md:text-lg font-bold text-white mt-2">{experience.company}</h2>
                  <p className="text-gray-400 text-[10px] mt-2">{experience.period} | {experience.location}</p>
                </div>
              </div>
              <p className="text-gray-300 mb-2 text-xs">{experience.summary}</p>
              <ul className="space-y-1 text-gray-300 text-[11px]">
                {(experience.details || []).map((item, index) => (
                  <li key={index} className="flex gap-3">
                    <span className="mt-1 text-green-400">•</span>
                    <span>{item}</span>
                  </li>
                ))}
              </ul>
            </motion.div>
          ))}
        </div>
      </div>
    </div>
  );
}
