import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Github, ExternalLink, ArrowLeft } from "lucide-react";
import { ALL_PROJECTS } from "../data/projectsData";

const VIEW_STORAGE_KEY = (id) => `portfolio_project_views_${id}`;
const SESSION_VIEWED_KEY = (id) => `portfolio_project_viewed_${id}`;

const useLiveProjectViews = (projectId, initialViews = 0) => {
  const [views, setViews] = useState(initialViews);

  useEffect(() => {
    if (typeof window === "undefined") return;

    const storageKey = VIEW_STORAGE_KEY(projectId);
    const sessionKey = SESSION_VIEWED_KEY(projectId);
    const storedViews = parseInt(localStorage.getItem(storageKey) ?? initialViews, 10) || initialViews;

    if (!sessionStorage.getItem(sessionKey)) {
      const nextViews = storedViews + 1;
      localStorage.setItem(storageKey, nextViews.toString());
      sessionStorage.setItem(sessionKey, "1");
      setViews(nextViews);
    } else {
      setViews(storedViews);
    }
  }, [projectId, initialViews]);

  return views;
};

export default function ProjectsPage({ onNavigate }) {
  const [filterTag, setFilterTag] = useState("all");
  const [sortBy, setSortBy] = useState("recent");

  const MAIN_TAGS = [
    "Artificial intelligence and Machine learning",
    "Quantitative finance",
    "Software engineering",
  ];

  const filteredProjects = filterTag === "all"
    ? ALL_PROJECTS
    : ALL_PROJECTS.filter((project) => project.mainTag === filterTag);

  const sortedProjects = [...filteredProjects].sort((a, b) => {
    if (sortBy === "recent") return new Date(b.date) - new Date(a.date);
    if (sortBy === "stars") return b.stars - a.stars;
    return 0;
  });

  const ProjectCard = ({ project }) => {
    const views = useLiveProjectViews(project.id, project.views ?? 0);

    return (
      <div className="bg-[#0d1117] border border-green-500/20 rounded-3xl p-6 text-left hover:border-green-400 hover:shadow-[0_0_15px_rgba(34,197,94,0.3)] transition">
        <div className="mb-3 inline-flex items-center gap-2 text-xs text-green-300">
          <span className="bg-green-500/10 border border-green-500/20 px-2 py-1 rounded-full">{project.mainTag}</span>
        </div>
        <div className="flex items-start justify-between gap-4 mb-3">
        <div>
          <h3 className="text-green-400 text-lg font-semibold">{project.title}</h3>
          <p className="text-gray-400 text-xs mt-1">{new Date(project.date).getFullYear()}</p>
        </div>
        <div className="flex gap-3 text-xs text-gray-400">
          <div className="flex items-center gap-1 group cursor-default">
            <span className="transition-transform duration-200 text-gray-400 group-hover:text-green-300 group-hover:scale-110">⭐</span>
            <span className="font-semibold text-gray-200">{project.stars}</span>
          </div>
          <div className="flex items-center gap-1 group cursor-default">
            <span className="transition-transform duration-200 text-gray-400 group-hover:text-green-300 group-hover:scale-110">👁️</span>
            <span className="font-semibold text-gray-200">{views}</span>
          </div>
        </div>
      </div>
      <p className="text-gray-300 text-sm mb-4">{project.description}</p>
      <div className="flex flex-wrap gap-2 mb-4">
        {project.tags.map((tag, index) => (
          <span key={index} className="bg-green-500/10 text-green-300 text-xs px-2.5 py-1 rounded-full border border-green-500/20">
            {tag}
          </span>
        ))}
      </div>
      <div className="flex items-center gap-3 text-sm text-gray-400 pt-3 border-t border-green-500/10">
        <a href={project.github} target="_blank" rel="noreferrer" className="hover:text-green-300 flex items-center gap-1">
          <Github size={14} /> Code
        </a>
        {project.live !== "#" && (
          <a href={project.live} target="_blank" rel="noreferrer" className="hover:text-green-300 flex items-center gap-1">
            <ExternalLink size={14} /> Live
          </a>
        )}
      </div>
    </div>
  );
};

  return (
    <div className="min-h-screen bg-[#0b0f16] text-white">
      <div className="pt-20 pb-10 px-6">
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="max-w-5xl mx-auto"
        >
          <button
            onClick={() => onNavigate?.("home")}
            className="inline-flex items-center gap-2 text-green-300 hover:text-white text-sm font-medium mb-6"
          >
            <ArrowLeft size={18} />
            Back to Portfolio
          </button>
          <div className="text-center">
            <h1 className="text-4xl md:text-5xl font-bold text-green-400 mb-3">Projects</h1>
            <p className="text-gray-400 text-lg">Quant research, ML systems, and engineering projects.</p>
          </div>
        </motion.div>
      </div>

      <div className="px-6 pb-14 max-w-6xl mx-auto">
        <div className="mb-8 flex flex-wrap items-center justify-between gap-3">
          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => setFilterTag("all")}
              className={`px-4 py-1.5 rounded-full text-sm font-medium transition ${
                filterTag === "all" ? "bg-green-500 text-black" : "bg-gray-700/40 text-gray-300 hover:bg-gray-600/50"
              }`}
            >
              All
            </button>
            {MAIN_TAGS.map((tag) => (
              <button
                key={tag}
                onClick={() => setFilterTag(tag)}
                className={`px-4 py-1.5 rounded-full text-sm font-medium transition ${
                  filterTag === tag ? "bg-green-500 text-black" : "bg-gray-700/40 text-gray-300 hover:bg-gray-600/50"
                }`}
              >
                {tag}
              </button>
            ))}
          </div>
          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
            className="px-3 py-1.5 rounded-lg bg-gray-700/40 text-gray-300 text-sm border border-gray-600/30 hover:border-gray-500/50 transition cursor-pointer"
          >
            <option value="recent">Recent</option>
            <option value="stars">Most Stars</option>
          </select>
        </div>

        <div className="space-y-5">
          {sortedProjects.map((project, idx) => (
            <motion.div
              key={project.id}
              initial={{ opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.04 }}
            >
              <ProjectCard project={project} />
            </motion.div>
          ))}
        </div>

        {sortedProjects.length === 0 && (
          <div className="text-center py-12">
            <p className="text-gray-400 text-lg">No projects found for this tag.</p>
          </div>
        )}
      </div>
    </div>
  );
}
