import { motion } from "framer-motion";
import React, { useState } from "react";

export default function ExperienceCard({ logo, logoText, logoColor, role, company, period, location, summary, details, aboutc }) {
  const [flipped, setFlipped] = useState(false);

  const LogoBadge = ({ size = "w-10 h-10" }) => logo ? (
    <img src={logo} alt={company} className={`${size} rounded-full object-contain`} />
  ) : (
    <div
      className={`${size} rounded-lg flex items-center justify-center text-white font-bold text-xs flex-shrink-0`}
      style={{ backgroundColor: logoColor || "#374151" }}
    >
      {logoText || company.charAt(0)}
    </div>
  );

  return (
    <motion.div
      className="relative w-full md:w-[420px] h-[300px] perspective"
      whileHover={{ scale: 1.03 }}
      transition={{ duration: 0.4 }}
    >
      <div
        className={`relative w-full h-full transition-transform duration-700 transform-style-preserve-3d ${flipped ? "rotate-y-180" : ""
          }`}
      >
        {/* FRONT SIDE */}
        <div
          className="absolute inset-0 bg-[#0b0f16] border border-green-500/40 rounded-2xl shadow-lg hover:border-green-400 hover:shadow-[0_0_25px_rgba(34,197,94,0.5)] backface-hidden p-6 flex flex-col items-start justify-between text-left overflow-hidden"
          onClick={() => setFlipped(true)}
        >

          <div className="flex items-center gap-3">
            <LogoBadge />

            <div>
              <h3 className="text-green-400 font-semibold text-lg">{role}</h3>
              <p className="text-gray-400 text-sm">{company}</p>
              <p className="text-gray-400 text-xs mb-3">
                {period} | {location}
              </p>
            </div>
          </div>
          <p className="text-gray-300 mt-3 text-sm italic line-clamp-3 flex-1">{summary}</p>
          <div className="w-full text-right text-green-400 text-sm font-semibold mt-4 cursor-pointer">
            Learn More →
          </div>

        </div>

        {/* BACK SIDE */}
        <div
          className="absolute inset-0 bg-[#0b0f16] border border-green-500/60 rounded-2xl shadow-lg rotate-y-180 backface-hidden p-6 text-left flex flex-col justify-between overflow-y-auto"
          onClick={() => setFlipped(false)}
        >


          <div>
            <h3 className="text-green-400 font-semibold text-lg">{role}</h3>
            <p className="text-gray-400 text-sm mb-2">{company}</p>
            <p className="text-gray-400 text-xs mb-3">
              {period} | {location}
            </p>
            <p className="text-gray-400 text-xs mb-3">
                {aboutc}
              </p>
            <ul className="list-disc list-inside text-gray-300 space-y-1 text-sm">
              {details.map((point, i) => (
                <li key={i}>{point}</li>
              ))}
            </ul>
          </div>
          <p className="text-right text-green-400 text-sm font-semibold mt-3 cursor-pointer">
            ← Back
          </p>
        </div>
      </div>
    </motion.div>
  );
}
